DIALOGS = [
[trp_sod_strategy_advisor, "sa_select_melee_infantry", [
		(try_begin),
			(eq, "$g_sod_sa_talk_subject", 11),
			(str_store_string, s1, "@Their infantry increases in experience from Recruits, Militia, Footmen, Infantry, to Sergeants.  There is really nothing spectacular about them, but they are always accompanied by ranged and cavalry support."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 12),
			(str_store_string, s1, "@Their infantry increases in experience from Recruits, Footmen, Veterans, Infantry, to Guards.  There is really nothing spectacular about them, but they are always accompanied by ranged infantry and cavalry support. They routinely hire the services of the Conquistadors to boost their main weakness, the infantry.  However, the Vaegir army is well balanced and composed of many different army branches."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 13),
			(str_store_string, s1, "@There is no melee infantry troop the Khergits will bring to the open battlefield.  Perhaps that is why they allow the Elephant Guard, who fights exclusively on foot, to settle on their lands. If you want to see the Khergit on foot you need to kill the horse they ride or bring the fight to their home.  But bring a shield my lord, I've never heard of a Khergit that does not own a bow."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 14),
			(str_store_string, s1, "@The Nord army is 100% infantry.  They range in skill from Recruits, Footmen, Trained Footmen, Warriors, Veterans, and their legendary Huscarls.  Do not underestimate their strength.  Even the mighty Antarians could learn a trick or two from the Nords. The heavy infantry of the Nords is known throughout this land and many a brave knight has fallen to their axes."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 15),
			(str_store_string, s1, "@The Rhodok army is 100% infantry.  They range in skill from Tribesmen, Spearmen, Trained Spearmen, Warriors, Veteran Spearmen, and their legendary Sergeants.  While not quite as tough as the Nords, their melee infantry is skilled and disciplined.  Charging head first into their spears is suicide. They will also never be without ranged support.  Taking a Rhodok castle is like storming  a Marinarian castle.  Their strategy involves heavy infantry covered by sharpshooters.  Simple, yet effective.  "),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 21),
			(str_store_string, s1, "@Antarians specialize in melee infantry.  Peasants rise to the ranks of Regulars, Veterans, and Elites.  They are heavily armored and specialize in two-handed weapons.  While vulnerable to missile fire, these are definitely guys you would not want up close when angry."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 22),
			(str_store_string, s1, "@The Marinians focus on two troop types, melee infantry and ranged infantry.  Their melee infantry in order of importance consists of Peasants, Conscripts, Regulars, Veterans, and Elites. While their elite infantry is not as powerful as the Antarians, their spears are more useful versus cavalry.  "),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 23),
			(str_store_string, s1, "@Despite popular belief, the Adenians do employ infantry.  They are not the greatest troops in the land but they get the job done.  Their structure consists of Peasants, Regulars, Veterans, and Elites."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 24),
			(str_store_string, s1, "@The Villianese have a remarkably strong light to medium infantry line.  Their ranks consist of Regulars, Veterans, and Elites.  While not effective versus heavy infantry, they are capable of holding their lines long enough for their archers to reposition themselves for the kill."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 37),
			(str_store_string, s1, "@The Boar Clan melee infantry consists of warriors and veteran warriors.  They primarily wield two-handed axes and hammers and wear at a minimum mail armor.  They are not as powerful as elite Antarian infantry, but they can give them a run for their money."),
		(else_try),
			(eq, "$g_sod_sa_talk_subject", 25),
			(str_store_string, s1, "@The Zerrikanian's infantry consists of peasants and slaves, militia, and axemen.  Their equipment is diverse but consists mostly of axes and clubs armored with leathers and laminar.  Their lower tier troops will form a shield wall while their axe men wield two handed double edged axes.  Nothing astonishing in terms of combat, but their soldiers are remarkably violent and brave."),
		(try_end),
	], "{s1}", "sa_select_3", []],
]
